import * as THREE from 'three';
import {createToyKit,disposeToyTree} from '../world/toy-kit.js';
import {signLabel} from '../world/handwriting.js';
import {LIBRARY_SHELVES,LIBRARY_RESIDENTS,libraryRolePoint} from '../world/library-layout.js';
import {QUEST_BOOKS,SHELF_TOPICS,shelfBooks,MISSIONS} from './quest-model.js';
export const DELIVERY_POINTS=Object.fromEntries(Object.entries({chinchilla:{x:-5.64,y:1.01,z:2.21},armadillo:{x:-2.1,y:.43,z:-3.965},capybara:{x:6.2,y:.76,z:-5.26}}).map(([id,p])=>[id,libraryRolePoint(id,p)]));
export const HANDOVER_GATES=Object.fromEntries(Object.entries({chinchilla:{x:-7.1,z:2.75},armadillo:{x:-3.85,z:-3.85},capybara:{x:7.8,z:-3.6}}).map(([id,p])=>[id,libraryRolePoint(id,p)]));
export const HANDOVER_WAYPOINTS=Object.fromEntries(Object.entries({chinchilla:{x:-6.78,y:1.02,z:2.1},armadillo:{x:-3.4,y:.68,z:-4.08},capybara:{x:7.34,y:.76,z:-5.26}}).map(([id,p])=>[id,libraryRolePoint(id,p)]));
HANDOVER_GATES.armadillo={x:-7.7,z:1.4};
HANDOVER_WAYPOINTS.armadillo={x:-7.15,y:.68,z:1.93};
export const questShelfApproach=i=>({x:LIBRARY_SHELVES[i].x-(i===1?.35:i===3?.08:0),z:LIBRARY_SHELVES[i].z+1.44});
export function createQuestView({zoneRoot,player,model,poser}){
 const root=new THREE.Group();root.name='library.quest';zoneRoot.add(root);const kit=createToyKit(root),books=new Map(),slots=new Map(),savedPose=poser.getState();let disposed=false,index=0,held=null,motion=null,acceptance=null;
 for(const[id,b]of Object.entries(QUEST_BOOKS)){const g=new THREE.Group();g.name='quest-book.'+id;root.add(g);kit.box(.06,.09,.34,b.color,-.38,0,0,.012,g);kit.box(.82,.014,.34,b.color,0,-.045,0,.006,g);kit.box(.75,.069,.315,'#fff6de',.012,0,0,.008,g);kit.box(.82,.014,.34,b.color,0,.045,0,.006,g);kit.box(.32,.006,.15,'#fff6de',.1,.056,0,.003,g);books.set(id,g);}
 for(const[shelf,s]of LIBRARY_SHELVES.entries()){kit.box(1.88,.055,.24,'#e1c28d',s.x,.8635,s.z+.40,.012);const approach=new THREE.Mesh(new THREE.RingGeometry(.13,.18,24),new THREE.MeshBasicMaterial({color:'#93a978',side:THREE.DoubleSide,transparent:true,opacity:.65,depthWrite:false}));approach.rotation.x=-Math.PI/2;approach.position.set(questShelfApproach(shelf).x,.063,questShelfApproach(shelf).z);root.add(approach);for(const side of [-1,1]){const label=signLabel(`${shelf+1} · ${SHELF_TOPICS[shelf]}`,s.x,2.39,s.z+side*.38,1.7,'#334f45','#fff1cf',root);if(label&&side<0)label.rotation.y=Math.PI;}}
 const marker=new THREE.Mesh(new THREE.RingGeometry(.16,.22,40),new THREE.MeshBasicMaterial({color:'#d6a747',side:THREE.DoubleSide,transparent:true,opacity:.85,depthWrite:false}));marker.rotation.x=-Math.PI/2;marker.position.y=.063;root.add(marker);
 function slot(id){const b=QUEST_BOOKS[id],shelf=index===3&&id==='seed-chair'?5:b.shelf,s=LIBRARY_SHELVES[shelf],offset=shelfBooks(index,shelf).length>1?(id==='seed-chair'?.5:-.5):0;return new THREE.Vector3(s.x+offset,.945,s.z+.47);}
 function carryPoint(){const a=poser.getAnchors();return new THREE.Vector3(...a.leftHand).add(new THREE.Vector3(...a.rightHand)).multiplyScalar(.5).add(new THREE.Vector3(0,-.022,.155));}
 function resetPose(){poser.setPose(savedPose.name,savedPose.amount,savedPose.time);}
 function setMission(i){if(disposed)return;index=i;held=null;motion=null;acceptance=null;resetPose();for(const[id,b]of books){root.add(b);const p=slot(id);slots.set(id,p.clone());b.position.copy(p);b.rotation.set(0,Math.PI,0);b.visible=true;}const m=MISSIONS[i],at=m.kind==='sort'?LIBRARY_SHELVES[m.recipient]:HANDOVER_GATES[m.recipient];marker.position.set(at.x,.063,at.z+(m.kind==='sort'?1.44:0));}
 function animateTo(book,targetParent,targetPosition,end,rotation=new THREE.Quaternion(),lift=.13,duration=.55){book.updateWorldMatrix(true,false);const from=book.getWorldPosition(new THREE.Vector3()),q=book.getWorldQuaternion(new THREE.Quaternion());root.attach(book);motion={book,from,q,parent:targetParent,point:targetPosition,rotation,lift,duration,elapsed:0,end};}
 function heldRotation(){root.updateWorldMatrix(true,false);model.updateWorldMatrix(true,false);return root.getWorldQuaternion(new THREE.Quaternion()).invert().multiply(model.getWorldQuaternion(new THREE.Quaternion()));}
 function shelfTransfer(book,p,intoHands,end){const waypoint=new THREE.Vector3(p.x,1.18,p.z+.58),hold=heldRotation(),shelfQ=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),Math.PI);if(intoHands)animateTo(book,root,waypoint,()=>animateTo(book,model,carryPoint(),end,new THREE.Quaternion(),0,.275),hold,.08,.275);else animateTo(book,root,waypoint,()=>animateTo(book,root,p,end,shelfQ,.08,.275),hold,0,.275);}
 function pick(id){if(disposed||held||motion||!books.has(id))return false;held=id;poser.setPose('readStanding',1,0);shelfTransfer(books.get(id),slots.get(id),true,()=>{});return true;}
 function returnBook(){if(!held||motion)return false;const id=held;shelfTransfer(books.get(id),slots.get(id),false,()=>{held=null;resetPose();});return true;}
 function deliver(){if(!held||motion||acceptance)return false;const m=MISSIONS[index],book=books.get(held);if(m.kind==='sort'){const s=LIBRARY_SHELVES[m.recipient];shelfTransfer(book,new THREE.Vector3(s.x,.945,s.z+.47),false,()=>{held=null;resetPose();});}else{const endpoint=DELIVERY_POINTS[m.recipient],waypoint=HANDOVER_WAYPOINTS[m.recipient];animateTo(book,root,new THREE.Vector3(waypoint.x,waypoint.y,waypoint.z),()=>animateTo(book,root,new THREE.Vector3(endpoint.x,endpoint.y,endpoint.z),()=>{acceptance={book,time:0};resetPose();},new THREE.Quaternion(),m.recipient==='capybara'?0:.13));}return true;}
 function step(dt){if(disposed||!Number.isFinite(dt)||dt<0)return;if(motion){const a=motion;a.elapsed=Math.min(a.duration,a.elapsed+dt);if(a.duration-a.elapsed<1e-9)a.elapsed=a.duration;const t=a.elapsed/a.duration,e=t*t*(3-2*t),target=a.parent.localToWorld(a.point.clone()),q=a.parent.getWorldQuaternion(new THREE.Quaternion()).multiply(a.rotation),p=a.from.clone().lerp(target,e);p.y+=Math.sin(Math.PI*t)*a.lift;root.worldToLocal(p);a.book.position.copy(p);const w=a.q.clone().slerp(q,e);a.book.quaternion.copy(root.getWorldQuaternion(new THREE.Quaternion()).invert().multiply(w));if(t===1){a.parent.add(a.book);a.book.position.copy(a.point);a.book.quaternion.copy(a.rotation);motion=null;a.end();}}else if(acceptance){acceptance.time+=dt;if(acceptance.time>=.45){acceptance.book.visible=false;acceptance=null;held=null;}}else if(held){const b=books.get(held);if(b.parent===model)b.position.copy(carryPoint());}}
 function tick(dt){if(!Number.isFinite(dt)||dt<0)return;let remaining=Math.min(dt,1);while(remaining>1e-9){const part=Math.min(remaining,1/120);step(part);remaining-=part;}}
 function dispose(){if(disposed)return;disposed=true;for(const b of books.values())root.attach(b);resetPose();disposeToyTree(root);}
 setMission(0);return{root,books,setMission,pick,returnBook,deliver,tick,dispose,get busy(){return !!motion||!!acceptance;},snapshot:()=>({held,busy:!!motion||!!acceptance,bookParents:[...books].map(([id,b])=>[id,b.parent?.name??''])})};
}
